"""Bounded local PDF metadata/rendering; paths are generated by the material service."""
import json
import math
import sys
import pymupdf

mode, source = sys.argv[1:3]
with pymupdf.open(source) as doc:
    if mode == "info":
        print(json.dumps({"pages": [{"width": p.rect.width, "height": p.rect.height, "rotation": p.rotation} for p in doc]}))
    elif mode == "render":
        page_number, target, bbox, dpi = sys.argv[3:7]
        page = doc[int(page_number) - 1]
        area = page.rect
        if bbox != "null":
            x0, y0, x1, y1 = json.loads(bbox)
            if not (0 <= x0 < x1 <= 1 and 0 <= y0 < y1 <= 1):
                raise ValueError("Invalid normalized crop rectangle")
            area = pymupdf.Rect(x0 * area.width, y0 * area.height, x1 * area.width, y1 * area.height)
        scale = min(float(dpi) / 72, math.sqrt(12000000 / (area.width * area.height)))
        pix = page.get_pixmap(matrix=pymupdf.Matrix(scale, scale), clip=area, alpha=False)
        pix.save(target)
        print(json.dumps({"width": pix.width, "height": pix.height, "rotation": page.rotation}))
    else:
        raise ValueError("Unsupported PDF helper operation")
